<?php
declare(strict_types=1);
require dirname(__DIR__) . '/bootstrap/app.php';
use App\Core\Database; use App\Core\Security;
$page = $_GET['page'] ?? 'home'; $user=Security::currentUser(); $error=''; $success='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    $action=$_POST['action'] ?? '';
    if (!Security::verifyCsrf($_POST['_csrf'] ?? null)) { http_response_code(419); $error='Your session token expired. Refresh and try again.'; }
    elseif ($action==='register') {
        $name=trim((string)($_POST['name']??'')); $email=strtolower(trim((string)($_POST['email']??''))); $password=(string)($_POST['password']??''); $role=$_POST['role']??'student';
        if ($name==='' || !filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($password)<10 || !in_array($role,['student','recruiter'],true)) $error='Enter a name, valid email, password of at least 10 characters, and a supported role.';
        else try { $db=Database::connection(); $db->beginTransaction(); $stmt=$db->prepare('INSERT INTO users (name,email,password_hash,role,status) VALUES (?,?,?,?,?)'); $stmt->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role,$role==='recruiter'?'pending':'active']); $id=(int)$db->lastInsertId(); if($role==='student') $db->prepare('INSERT INTO student_profiles (user_id) VALUES (?)')->execute([$id]); $db->commit(); $success='Account created. You can now sign in.'; $page='login'; } catch(Throwable $e) { if(isset($db)&&$db->inTransaction())$db->rollBack(); $error=($e instanceof PDOException && $e->getCode()==='23000')?'An account with that email already exists.':'Registration could not be completed. Check database setup and try again.'; }
    } elseif ($action==='login') {
        $email=strtolower(trim((string)($_POST['email']??''))); $password=(string)($_POST['password']??'');
        try { $stmt=Database::connection()->prepare('SELECT id,name,email,password_hash,role,status FROM users WHERE email=? LIMIT 1'); $stmt->execute([$email]); $row=$stmt->fetch(); if($row && $row['status']==='active' && password_verify($password,$row['password_hash'])) { session_regenerate_id(true); unset($row['password_hash']); $_SESSION['user']=$row; header('Location: index.php?page=dashboard'); exit; } $error='Invalid credentials, or this account is awaiting approval/inactive.'; } catch(Throwable $e) { $error='Database is not ready. Import database/schema.sql and configure .env first.'; }
    } elseif ($action==='save_profile') {
        Security::requireRole(['student']);
        $name=trim((string)($_POST['name']??'')); $phone=trim((string)($_POST['phone']??'')); $branch=trim((string)($_POST['branch']??'')); $degree=trim((string)($_POST['degree']??'')); $semester=trim((string)($_POST['semester']??'')); $cgpa=trim((string)($_POST['cgpa']??'')); $year=trim((string)($_POST['graduation_year']??'')); $bio=trim((string)($_POST['bio']??''));
        if($name==='' || mb_strlen($name)>120 || mb_strlen($phone)>30 || mb_strlen($branch)>120 || mb_strlen($degree)>120 || mb_strlen($bio)>3000 || ($semester!=='' && (!ctype_digit($semester)||(int)$semester<1||(int)$semester>20)) || ($cgpa!=='' && (!is_numeric($cgpa)||(float)$cgpa<0||(float)$cgpa>10)) || ($year!=='' && (!ctype_digit($year)||(int)$year<2000||(int)$year>2150))) $error='Please check your profile fields. CGPA must be between 0 and 10, semester between 1 and 20, and graduation year must be valid.';
        else try { $db=Database::connection(); $db->beginTransaction(); $db->prepare("UPDATE users SET name=? WHERE id=? AND role='student'")->execute([$name,(int)$user['id']]); $stmt=$db->prepare('INSERT INTO student_profiles (user_id,phone,branch,degree,semester,cgpa,graduation_year,bio) VALUES (?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE phone=VALUES(phone),branch=VALUES(branch),degree=VALUES(degree),semester=VALUES(semester),cgpa=VALUES(cgpa),graduation_year=VALUES(graduation_year),bio=VALUES(bio)'); $stmt->execute([(int)$user['id'],$phone?:null,$branch?:null,$degree?:null,$semester!==''?(int)$semester:null,$cgpa!==''?(float)$cgpa:null,$year!==''?(int)$year:null,$bio?:null]); $db->commit(); $_SESSION['user']['name']=$name; $user=$_SESSION['user']; $success='Your student profile has been saved.'; $page='profile'; } catch(Throwable $e) { if(isset($db)&&$db->inTransaction())$db->rollBack(); $error='Profile could not be saved. Check the database setup and try again.'; $page='profile'; }
    } elseif ($action==='save_skills') {
        Security::requireRole(['student']); $raw=trim((string)($_POST['skills']??''));
        if(mb_strlen($raw)>2000) { $error='Please keep the skills list under 2,000 characters.'; $page='profile'; }
        else try { $db=Database::connection(); $names=array_values(array_unique(array_filter(array_map(fn($v)=>mb_substr(trim($v),0,100),explode(',',$raw)),fn($v)=>$v!==''))); $db->beginTransaction(); $db->prepare('DELETE FROM student_skills WHERE student_id=?')->execute([(int)$user['id']]); $find=$db->prepare('SELECT id FROM skills WHERE name=?'); $insert=$db->prepare('INSERT INTO skills (name) VALUES (?)'); $link=$db->prepare('INSERT INTO student_skills (student_id,skill_id,proficiency) VALUES (?,?,?)'); foreach($names as $name){$find->execute([$name]);$id=$find->fetchColumn();if(!$id){try{$insert->execute([$name]);$id=$db->lastInsertId();}catch(PDOException $ex){$find->execute([$name]);$id=$find->fetchColumn();}}if($id)$link->execute([(int)$user['id'],(int)$id,'beginner']);} $db->commit(); $success='Your skills have been updated.'; $page='profile'; } catch(Throwable $e) { if(isset($db)&&$db->inTransaction())$db->rollBack(); $error='Skills could not be saved. Check the database setup and try again.'; $page='profile'; }
    } elseif ($action==='logout') { $_SESSION=[]; if(ini_get('session.use_cookies')) { $params=session_get_cookie_params(); setcookie(session_name(),'',time()-42000,$params['path'],$params['domain']??'',(bool)$params['secure'],(bool)$params['httponly']); } session_destroy(); header('Location: index.php'); exit; }
}
if($page==='logout' && $user){$page='dashboard';}
if(in_array($page,['dashboard','profile'],true) && !$user){header('Location: index.php?page=login');exit;}
if($page==='profile' && $user && $user['role']!=='student'){http_response_code(403);$page='forbidden';}
if($page==='profile' && $user && $user['role']==='student'){try{$db=Database::connection();$q=$db->prepare('SELECT u.name,u.email,p.* FROM users u LEFT JOIN student_profiles p ON p.user_id=u.id WHERE u.id=? AND u.role=\'student\'');$q->execute([(int)$user['id']]);$profile=$q->fetch()?:[];$q=$db->prepare('SELECT s.name FROM student_skills ss JOIN skills s ON s.id=ss.skill_id WHERE ss.student_id=? ORDER BY s.name');$q->execute([(int)$user['id']]);$profileSkills=array_column($q->fetchAll(),'name');}catch(Throwable $e){$profileError=true;$profile=[];$profileSkills=[];}}
if($page==='dashboard' && $user){
  try { $db=Database::connection(); $counts=['jobs'=>(int)$db->query("SELECT COUNT(*) FROM jobs WHERE status='published' AND (closes_at IS NULL OR closes_at>=NOW())")->fetchColumn()]; if($user['role']==='student'){$s=$db->prepare('SELECT * FROM student_profiles WHERE user_id=?');$s->execute([$user['id']]);$profile=$s->fetch()?:[];$a=$db->prepare('SELECT COUNT(*) FROM applications WHERE student_id=?');$a->execute([$user['id']]);$counts['applications']=(int)$a->fetchColumn();} elseif($user['role']==='recruiter'){$s=$db->prepare('SELECT COUNT(*) FROM jobs j JOIN recruiter_profiles r ON r.company_id=j.company_id WHERE r.user_id=?');$s->execute([$user['id']]);$counts['my_jobs']=(int)$s->fetchColumn();} else {$counts['users']=(int)$db->query('SELECT COUNT(*) FROM users')->fetchColumn();$counts['applications']=(int)$db->query('SELECT COUNT(*) FROM applications')->fetchColumn();} } catch(Throwable $e) {$dbError=true;}
}
function e(?string $s): string { return htmlspecialchars($s??'',ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
$csrf=Security::csrfToken();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#050505"><title><?= e(\App\Core\Env::get('APP_NAME','AI Campus Placement Portal')) ?></title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"><link rel="stylesheet" href="assets/css/app.css"><script src="https://unpkg.com/lucide@latest"></script></head><body>
