<?php elseif($page==='login'||$page==='register'): ?><main class="auth-wrap"><div class="auth-card"><p class="eyebrow">CAREER/INTEL ACCESS</p><h1><?=$page==='login'?'Welcome back.':'Start with a clear path.'?></h1><p class="muted"><?=$page==='login'?'Sign in to continue to your portal.':'Create an account to begin your placement journey.'?></p><form method="post" class="auth-form"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="<?=$page==='login'?'login':'register'?>"><?php if($page==='register'): ?><label>Full name<input class="form-control" name="name" required maxlength="120" autocomplete="name"></label><?php endif; ?><label>Email address<input class="form-control" type="email" name="email" required maxlength="190" autocomplete="email"></label><label>Password<input class="form-control" type="password" name="password" required minlength="<?=$page==='register'?'10':'1'?>" autocomplete="<?=$page==='login'?'current-password':'new-password'?>"><?php if($page==='register'): ?><small>Use at least 10 characters.</small><?php endif; ?></label><?php if($page==='register'): ?><label>Account type<select class="form-select" name="role"><option value="student">Student</option><option value="recruiter">Recruiter / Company</option></select><small>Recruiter accounts require approval before sign-in.</small></label><?php endif; ?><button class="primary-btn w-100" type="submit"><?=$page==='login'?'Sign in securely':'Create account'?> ↗</button></form><p class="auth-switch"><?=$page==='login'?"New here?":"Already registered?"?> <a href="index.php?page=<?=$page==='login'?'register':'login'?>"><?=$page==='login'?'Create an account':'Sign in'?></a></p></div></main>
<?php elseif($page==='profile' && $user && $user['role']==='student'): ?><main class="dashboard container"><div class="dash-top"><div><p class="eyebrow">STUDENT WORKSPACE</p><h1>Your profile.</h1><p class="muted">Keep your academic details and skills current for more useful career-fit results.</p></div><a class="secondary-btn" href="index.php?page=dashboard">Back to dashboard</a></div><?php if(!empty($profileError)): ?><div class="empty-state">Profile data could not be loaded. Check the database setup.</div><?php else: ?><section class="panel mt-4"><h2>Academic and personal details</h2><form method="post" class="auth-form"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="save_profile"><label>Full name<input class="form-control" name="name" required maxlength="120" value="<?=e((string)($profile['name']??$user['name']))?>"></label><label>Email address<input class="form-control" value="<?=e((string)($profile['email']??$user['email']))?>" disabled><small>Email changes are not supported in this form.</small></label><label>Phone<input class="form-control" name="phone" maxlength="30" value="<?=e((string)($profile['phone']??''))?>"></label><label>Degree<input class="form-control" name="degree" maxlength="120" placeholder="e.g. B.Tech Computer Science" value="<?=e((string)($profile['degree']??''))?>"></label><label>Branch<input class="form-control" name="branch" maxlength="120" placeholder="e.g. Computer Engineering" value="<?=e((string)($profile['branch']??''))?>"></label><div class="row g-3"><div class="col-md-4"><label>Semester<input class="form-control" type="number" min="1" max="20" name="semester" value="<?=e((string)($profile['semester']??''))?>"></label></div><div class="col-md-4"><label>CGPA (0–10)<input class="form-control" type="number" min="0" max="10" step="0.01" name="cgpa" value="<?=e((string)($profile['cgpa']??''))?>"></label></div><div class="col-md-4"><label>Graduation year<input class="form-control" type="number" min="2000" max="2150" name="graduation_year" value="<?=e((string)($profile['graduation_year']??''))?>"></label></div></div><label>About you<textarea class="form-control" name="bio" rows="4" maxlength="3000" placeholder="A short professional introduction"><?=e((string)($profile['bio']??''))?></textarea></label><button class="primary-btn" type="submit">Save profile ↗</button></form></section><section class="panel mt-4"><h2>Skills</h2><p class="muted">Enter skills separated by commas. Skill names are normalized by trimming whitespace; this form does not claim verification.</p><form method="post" class="auth-form"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="save_skills"><label>Your skills<textarea class="form-control" name="skills" rows="3" maxlength="2000" placeholder="PHP, MySQL, JavaScript, Git"><?=e(implode(', ',$profileSkills??[]))?></textarea></label><button class="primary-btn" type="submit">Save skills ↗</button></form></section><?php endif; ?></main>
