<?php elseif($page==='dashboard' && $user): ?><main class="dashboard container"><div class="dash-top"><div><p class="eyebrow"><?=e(strtoupper($user['role']))?> WORKSPACE</p><h1>Good to see you, <?=e($user['name'])?>.</h1><p class="muted">Your portal is connected to live database records.</p></div><span class="status-pill">● Account active</span></div><?php if(!empty($dbError)): ?><div class="empty-state">Database connection is unavailable. Check the local setup and database import.</div><?php else: ?><div class="metric-grid"><?php foreach(($counts??[]) as $label=>$value): ?><article class="metric-card"><p><?=e(ucwords(str_replace('_',' ',$label)))?></p><strong><?= (int)$value ?></strong><small>Current database total</small></article><?php endforeach; ?></div><?php endif; ?><section class="panel mt-4"><h2>Next steps</h2><p class="muted">The portal starts with an empty database. Your dashboard will fill as real profiles, jobs, and applications are added.</p><?php if($user['role']==='student'): ?><a class="secondary-btn" href="index.php?page=jobs">Browse opportunities (coming in Phase 2)</a><?php elseif(in_array($user['role'],['admin','tpo'],true)): ?><p class="muted">Administrative tools are being expanded in the next implementation phase.</p><?php else: ?><p class="muted">Company approval and job management workflows are part of the recruiter module.</p><?php endif; ?></section></main>
<?php else: ?><main class="container dashboard"><div class="empty-state"><h1>Page not found</h1><p>This route is not available yet.</p><a class="primary-btn" href="index.php">Return home</a></div></main><?php endif; ?>
